    a.source_gloss_snapshot,
    'verified_derived'::text as status,
    jsonb_build_object(
      'phase','FASE_H_BLOQUE_3',
      'batch_id','fase_h_es_nombres_wikidata_rv1909_anchor_001_20260820',
      'tipnr_id',a.tipnr_id,
