      'rv1909_provider_version','94e154b2e6e56eda1702d9e9f664357a5f2aa82634b551111b0b698d124e97d5',
      'source_identity_license','CC BY 4.0',
      'rv1909_anchor_validation','accent-preserving exact Spanish alias in exact TIPNR anchor verse',
      'rv1909_validation_source','rv1909-ebible',
      'rv1909_used_as_validation',true
    ),
    '2026-08-20 21:54:25.117652+00'::timestamptz,
    '2026-08-20 21:54:25.117652+00'::timestamptz
  from alias_rows a
), restored as (
  insert into public.biblical_hebrew_spanish_glosses
  (lexical_entry_id,display_gloss_es,alternative_glosses_es,confidence,derivation_method,source_gloss_snapshot,status,provenance,created_at,updated_at)
  select lexical_entry_id,display_gloss_es,alternative_glosses_es,confidence,derivation_method,source_gloss_snapshot,status,provenance,created_at,updated_at
  from restore_rows
  on conflict (lexical_entry_id) do update set
    display_gloss_es=excluded.display_gloss_es,
    alternative_glosses_es=excluded.alternative_glosses_es,
    confidence=excluded.confidence,
    derivation_method=excluded.derivation_method,
    source_gloss_snapshot=excluded.source_gloss_snapshot,
    status=excluded.status,
    provenance=excluded.provenance,
    created_at=excluded.created_at,
    updated_at=excluded.updated_at
  returning lexical_entry_id
)
select count(*) as restored_rows from restored;

